 * A cursor over a single line of the configuration document. Lines never
 * span directives, so every syntactic element the parser needs (names,
 * values, headers) lives on one line and can be scanned with a plain index.
 */

const BARE_CHAR = /[A-Za-z0-9_-]/

export class Scanner {
  constructor(line) {
    this.line = line
    this.pos = 0
  }

  peek() {
    return this.pos < this.line.length ? this.line[this.pos] : undefined
  }

  skipWs() {
    while (this.pos < this.line.length && (this.line[this.pos] === ' ' || this.line[this.pos] === '\t')) {
      this.pos++
    }
  }

  /** Skips whitespace, then swallows a `#`/`;` comment to the end of the line, if one starts here. */
  consumeCommentIfAny() {
    this.skipWs()
    const c = this.peek()
    if (c === '#' || c === ';') {
      this.pos = this.line.length
    }
  }

  atEnd() {
    return this.pos >= this.line.length
  }
}

function fail(reason) {
  throw { reason }
}

export function parseBasicString(scanner) {
  scanner.pos++ // consume opening quote
  let result = ''
  while (true) {
    if (scanner.pos >= scanner.line.length) fail('unterminated string')
    const c = scanner.line[scanner.pos]
    if (c === '"') {
      scanner.pos++
      return { kind: 'string', value: result }
    }
    if (c === '\\') {
      scanner.pos++
      if (scanner.pos >= scanner.line.length) fail('unterminated string')
      const e = scanner.line[scanner.pos]
      switch (e) {
        case '"':
          result += '"'
          scanner.pos++
          break
        case '\\':
          result += '\\'
          scanner.pos++
          break
        case 'n':
          result += '\n'
          scanner.pos++
          break
        case 't':
          result += '\t'
          scanner.pos++
          break
        case 'r':
          result += '\r'
          scanner.pos++
          break
        case '0':
          result += '\0'
          scanner.pos++
          break
        case 'u': {
          const hex = scanner.line.slice(scanner.pos + 1, scanner.pos + 5)
          if (hex.length !== 4 || !/^[0-9a-fA-F]{4}$/.test(hex)) fail('invalid escape \\u')
          result += String.fromCharCode(parseInt(hex, 16))
          scanner.pos += 5
          break
        }
        default:
          fail(`invalid escape \\${e}`)
      }
    } else {
      result += c
      scanner.pos++
    }
  }
}

export function parseLiteralString(scanner) {
  scanner.pos++ // consume opening quote
  const start = scanner.pos
  while (true) {
    if (scanner.pos >= scanner.line.length) fail('unterminated string')
    if (scanner.line[scanner.pos] === "'") {
      const value = scanner.line.slice(start, scanner.pos)
      scanner.pos++
      return { kind: 'string', value }
    }
    scanner.pos++
  }
}

export function parseName(scanner) {
  scanner.skipWs()
  const c = scanner.peek()
  if (c === '"') return parseBasicString(scanner).value
  if (c === "'") return parseLiteralString(scanner).value
  if (c !== undefined && BARE_CHAR.test(c)) {
    const start = scanner.pos
    while (scanner.pos < scanner.line.length && BARE_CHAR.test(scanner.line[scanner.pos])) {
      scanner.pos++
    }
    return scanner.line.slice(start, scanner.pos)
  }
  fail('expected a name')
}

export function parseDottedName(scanner) {
  const parts = [parseName(scanner)]
  while (true) {
    scanner.skipWs()
    if (scanner.peek() === '.') {
      scanner.pos++
      parts.push(parseName(scanner))
    } else {
      break
    }
  }
  return parts
}
"}

