 * Builds the document's node tree from the input text: one table/array/value
 * node per name, tracking header ownership so the redefinition rules in the
 * spec can be enforced. Node shapes:
 *   { kind: 'table', map: Map<string, node>, headerClosed: boolean }
 *   { kind: 'array-of-tables', items: node[] }   // node.kind === 'table'
 *   { kind: 'array', items: node[] }
 *   { kind: 'string' | 'boolean', value }
 *   { kind: 'integer', value: BigInt }
 *   { kind: 'float', value: number }
 */

import { Scanner, parseDottedName } from './scanner.js'
import { appendKey } from './paths.js'
import { parseValue } from './values.js'

function fail(reason) {
  throw { reason }
}

export function makeTableNode() {
  return { kind: 'table', map: new Map(), headerClosed: false }
}

/**
 * Walks the leading segments of a dotted name from `tableNode`, creating
 * intermediate tables as needed and descending into the last element of an
 * array of tables. Returns the map and key that the final segment should be
 * read from or written to, without assigning it.
 */
export function beginAssign(tableNode, segments, basePath) {
  let current = tableNode
  let curPath = basePath
  for (let i = 0; i < segments.length - 1; i++) {
    const seg = segments[i]
    curPath = appendKey(curPath, seg)
    let child = current.map.get(seg)
    if (child === undefined) {
      child = makeTableNode()
      current.map.set(seg, child)
    } else if (child.kind === 'table') {
      // descend
    } else if (child.kind === 'array-of-tables') {
      child = child.items[child.items.length - 1]
    } else {
      fail(`${curPath} is not a table`)
    }
    current = child
  }
  const lastSeg = segments[segments.length - 1]
  const finalPath = appendKey(curPath, lastSeg)
  return { targetMap: current.map, lastSeg, finalPath }
}

export function commitAssign(targetMap, lastSeg, finalPath, valueNode) {
  if (targetMap.has(lastSeg)) fail(`key ${finalPath} is defined twice`)
  targetMap.set(lastSeg, valueNode)
}

function processHeader(root, segments, isArray) {
  let current = root
  let curPath = ''
  for (let i = 0; i < segments.length - 1; i++) {
    const seg = segments[i]
    curPath = appendKey(curPath, seg)
    let child = current.map.get(seg)
    if (child === undefined) {
      child = makeTableNode()
      current.map.set(seg, child)
    } else if (child.kind === 'table') {
      // descend
    } else if (child.kind === 'array-of-tables') {
      child = child.items[child.items.length - 1]
    } else {
      fail(`${curPath} is not a table`)
    }
    current = child
  }
  const lastSeg = segments[segments.length - 1]
  const finalPath = appendKey(curPath, lastSeg)
  let child = current.map.get(lastSeg)
  if (!isArray) {
    if (child === undefined) {
      child = makeTableNode()
      child.headerClosed = true
      current.map.set(lastSeg, child)
      return { node: child, path: finalPath }
    }
    if (child.kind !== 'table') fail(`${finalPath} is not a table`)
    if (child.headerClosed) fail(`table ${finalPath} is defined twice`)
    child.headerClosed = true
    return { node: child, path: finalPath }
  }
  if (child === undefined) {
    child = { kind: 'array-of-tables', items: [] }
    current.map.set(lastSeg, child)
  }
  if (child.kind !== 'array-of-tables') fail(`${finalPath} is not an array of tables`)
  const table = makeTableNode()
  child.items.push(table)
  return { node: table, path: finalPath }
