 * Renders a document's node tree (see document.js) as canonical JSON or as
 * the `keys` listing.
 */

import { appendKey, appendIndex } from './paths.js'

function codePointCompare(a, b) {
  const ca = Array.from(a)
  const cb = Array.from(b)
  const len = Math.min(ca.length, cb.length)
  for (let i = 0; i < len; i++) {
    const diff = ca[i].codePointAt(0) - cb[i].codePointAt(0)
    if (diff !== 0) return diff
  }
  return ca.length - cb.length
}

function sortedKeys(tableNode) {
  return [...tableNode.map.keys()].sort(codePointCompare)
}

export function typeName(node) {
  switch (node.kind) {
    case 'table':
      return 'table'
    case 'array':
    case 'array-of-tables':
      return 'array'
    default:
      return node.kind
  }
}

function scalarToJSON(node) {
  switch (node.kind) {
    case 'string':
      return JSON.stringify(node.value)
    case 'integer':
      return node.value.toString()
    case 'float':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    default:
      throw new Error(`unreachable node kind ${node.kind}`)
  }
}

function toJSON(node, depth) {
  const pad = '  '.repeat(depth)
  const padIn = '  '.repeat(depth + 1)
  if (node.kind === 'table') {
    const keys = sortedKeys(node)
    if (keys.length === 0) return '{}'
    const lines = keys.map((k) => `${padIn}${JSON.stringify(k)}: ${toJSON(node.map.get(k), depth + 1)}`)
    return `{\n${lines.join(',\n')}\n${pad}}`
  }
  if (node.kind === 'array' || node.kind === 'array-of-tables') {
    if (node.items.length === 0) return '[]'
    const lines = node.items.map((item) => `${padIn}${toJSON(item, depth + 1)}`)
    return `[\n${lines.join(',\n')}\n${pad}]`
  }
  return scalarToJSON(node)
}

export function formatJSON(root) {
  return `${toJSON(root, 0)}\n`
}

function walkKeys(node, path, out) {
  out.push(`${path} ${typeName(node)}`)
  if (node.kind === 'table') {
    for (const k of sortedKeys(node)) walkKeys(node.map.get(k), appendKey(path, k), out)
  } else if (node.kind === 'array' || node.kind === 'array-of-tables') {
    node.items.forEach((item, i) => walkKeys(item, appendIndex(path, i), out))
  }
}

export function formatKeys(root) {
  const out = []
  for (const k of sortedKeys(root)) walkKeys(root.map.get(k), k, out)
  return out.length === 0 ? '' : `${out.join('\n')}\n`
}
