/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { readFileSync } from 'node:fs'
import { buildDocument } from './document.js'
import { formatJSON, formatKeys } from './format.js'

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'json' && mode !== 'keys')) {
    process.stderr.write('error: usage: cli.js json|keys\n')
    process.exit(2)
  }

  const input = readFileSync(0, 'utf8')

  let root
  try {
    root = buildDocument(input)
  } catch (e) {
    process.stderr.write(`error: ${e.message}\n`)
    process.exit(2)
    return
  }

  process.stdout.write(mode === 'json' ? formatJSON(root) : formatKeys(root))
  process.exit(0)
}

main()
"}

